const AJV_EQUAL_RUNTIME_MODULE = "ajv/dist/runtime/equal.js";
const AJV_UCS2_RUNTIME_REQUIRE =
  /const ([A-Za-z_$][A-Za-z0-9_$]*) = require\("ajv\/dist\/runtime\/ucs2length"\)\.default;/gu;
const AJV_EQUAL_RUNTIME_REQUIRE =
  /const ([A-Za-z_$][A-Za-z0-9_$]*) = require\("ajv\/dist\/runtime\/equal"\)\.default;/gu;
const COMMONJS_RUNTIME_LINK = /\brequire\(|\bmodule\.exports\b|\bexports\./u;
const REDUNDANT_MODULE_STRICT_PREFIX = '"use strict";';

interface DashboardSchemaDefinition {
  readonly fileName: string;
  readonly schemaId: string;
  readonly typeName: string;
}

interface ResolverFile {
  readonly url: string;
}

interface SchemaCompilerOptions {
  readonly $refOptions: {
    readonly resolve: {
      readonly file: false;
      readonly http: false;
      readonly repository: {
        readonly canRead: (file: ResolverFile) => boolean;
        readonly order: number;
        readonly read: (file: ResolverFile) => Promise<GeneratorSchema>;
      };
    };
  };
  readonly additionalProperties: false;
  readonly bannerComment: string;
  readonly cwd: string;
  readonly customName: (schema: GeneratorSchema) => string | undefined;
  readonly declareExternallyReferenced: true;
  readonly enableConstEnums: false;
  readonly format: true;
  readonly ignoreMinAndMaxItems: true;
  readonly strictIndexSignatures: true;
  readonly style: {
    readonly bracketSpacing: true;
    readonly printWidth: number;
    readonly semi: true;
    readonly singleQuote: false;
    readonly trailingComma: "all";
  };
  readonly unknownAny: true;
}

type GeneratorSchema = Record<string, unknown>;
type SchemaCompiler = (
  schema: GeneratorSchema,
  name: string,
  options: SchemaCompilerOptions,
) => Promise<string>;

