const dashboardRoot = dirname(dirname(fileURLToPath(import.meta.url)));
const schemaRoot = resolve(dashboardRoot, "../../schemas/v1");
const dashboardSchemaRoot = resolve(schemaRoot, "dashboard");
const generatedRoot = resolve(dashboardRoot, "src/contracts/generated");
const generatedRuntimeDirectory = "runtime";
const knownTypeNames: ReadonlyMap<string, string> = new Map(
  dashboardSchemas.map(({ schemaId, typeName }) => [schemaId, typeName] as const),
);

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isStringArray(value: unknown): value is string[] {
  return Array.isArray(value) && value.every((member: unknown) => typeof member === "string");
}

function loadSchemaCompiler(): SchemaCompiler {
  const require = createRequire(import.meta.url);
  const compilerModule: unknown = require("json-schema-to-typescript");
  if (!isRecord(compilerModule) || typeof compilerModule["compile"] !== "function") {
    throw new TypeError("json-schema-to-typescript does not expose its compile function");
  }
  const compiler = compilerModule["compile"];
  return async (schema, name, options) => {
    const output: unknown = await Reflect.apply(compiler, undefined, [schema, name, options]);
    if (typeof output !== "string") {
      throw new TypeError("json-schema-to-typescript returned a non-string result");
    }
    return output;
  };
}

const compileSchema = loadSchemaCompiler();

function normalizeReferenceSiblings(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((member) => normalizeReferenceSiblings(member));
  }
  if (!isRecord(value)) {
    return value;
  }

  const normalized = Object.fromEntries(
    Object.entries(value).map(([key, member]) => [key, normalizeReferenceSiblings(member)]),
  );
  const reference = normalized["$ref"];
  if (typeof reference !== "string" || Object.keys(normalized).length === 1) {
    return normalized;
  }

  const siblings = Object.fromEntries(Object.entries(normalized).filter(([key]) => key !== "$ref"));
  return { allOf: [{ $ref: reference }, siblings] };
}

function parseSchema(raw: string, source: string): GeneratorSchema {
  let parsed: unknown;
  try {
    parsed = JSON.parse(raw) as unknown;
  } catch (error: unknown) {
    throw new Error(`Cannot parse schema ${source}`, { cause: error });
  }
  if (!isRecord(parsed)) {
    throw new TypeError(`Schema ${source} must contain a JSON object`);
  }
  return normalizeReferenceSiblings(parsed) as GeneratorSchema;
}

function withoutRuntimeAnnotations(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((member) => withoutRuntimeAnnotations(member));
  }
  if (!isRecord(value)) {
    return value;
  }
  return Object.fromEntries(
    Object.entries(value)
      .filter(([key]) => key !== "$id" && key !== "$schema" && key !== "description")
      .map(([key, member]) => [key, withoutRuntimeAnnotations(member)]),
  );
}

function factorRuntimeClosedObjectUnions(value: unknown): unknown {
  if (Array.isArray(value)) {
    return value.map((member) => factorRuntimeClosedObjectUnions(member));
  }
  if (!isRecord(value)) {
    return value;
  }
  const transformed = Object.fromEntries(
    Object.entries(value).map(([key, member]) => [key, factorRuntimeClosedObjectUnions(member)]),
  );
  const variants = transformed["anyOf"];
  if (!Array.isArray(variants) || variants.length < 2) {
    return transformed;
  }
  const closedObjects = variants.filter(
    (variant): variant is GeneratorSchema =>
      isRecord(variant) &&
      variant["type"] === "object" &&
      variant["additionalProperties"] === false &&
      isRecord(variant["properties"]) &&
      isStringArray(variant["required"]),
  );
  if (closedObjects.length !== variants.length) {
    return transformed;
  }
  const firstProperties = closedObjects[0]?.["properties"];
  if (!isRecord(firstProperties)) {
    return transformed;
  }
  const commonPropertyNames = Object.keys(firstProperties).filter((propertyName) =>
    closedObjects.every((variant) => {
      const properties = variant["properties"];
      const required = variant["required"];
      return (
        isRecord(properties) &&
        isStringArray(required) &&
        required.includes(propertyName) &&
        JSON.stringify(properties[propertyName]) === JSON.stringify(firstProperties[propertyName])
      );
    }),
  );
  if (commonPropertyNames.length === 0) {
    return transformed;
  }
  const commonProperties = Object.fromEntries(
    commonPropertyNames.map((propertyName) => [propertyName, firstProperties[propertyName]]),
  );
  const commonNames = new Set(commonPropertyNames);
  const residualVariants = closedObjects.map((variant) => {
    const properties = variant["properties"];
    if (!isRecord(properties)) {
      throw new Error("Closed object union lost its properties during runtime factoring");
    }
    return {
      ...variant,
      properties: Object.fromEntries(
        Object.entries(properties).map(([propertyName, propertySchema]) => [
          propertyName,
          commonNames.has(propertyName) ? {} : propertySchema,
        ]),
      ),
    };
  });
  const siblings = { ...transformed };
  Reflect.deleteProperty(siblings, "anyOf");
  return {
    ...siblings,
    allOf: [
      { properties: commonProperties, required: commonPropertyNames, type: "object" },
      { anyOf: residualVariants },
    ],
  };
}

function runtimeOptimizedSchema(
  definition: DashboardSchemaDefinition,
  schema: GeneratorSchema,
): GeneratorSchema {
  if (definition.fileName === "dashboard-snapshot") {
    const properties = schema["properties"];
    if (!isRecord(properties) || !isRecord(properties["timeline"])) {
      throw new Error("Dashboard snapshot schema must expose its timeline property");
    }
    return {
      ...schema,
      properties: {
        ...properties,
        timeline: {
          ...properties["timeline"],
          items: {
            allOf: [
              {
                $ref: `${RESERVED_SCHEMA_ORIGIN}${RESERVED_SCHEMA_PREFIX}dashboard/ordered-dashboard-event.schema.json`,
              },
              {
                properties: {
                  event: {
                    properties: { kind: { not: { const: "droneTelemetry" } } },
                    required: ["kind"],
                    type: "object",
                  },
                },
                required: ["event"],
                type: "object",
              },
            ],
          },
        },
      },
    };
  }
  if (definition.fileName !== "dashboard-event") {
    return schema;
  }
  const variants = schema["anyOf"];
  const definitions = schema["$defs"];
  if (!Array.isArray(variants) || !isRecord(definitions)) {
    throw new Error("Dashboard event schema must expose its closed local variant union");
  }
  const envelopePropertyNames = ["kind", "eventClass", "mission", "time", "data"];
  let missionSchema: unknown;
  let timeSchema: unknown;
  const factoredVariants = variants.map((variant) => {
    if (!isRecord(variant) || typeof variant["$ref"] !== "string") {
      throw new Error("Dashboard event variants must be local definition references");
    }
    const definitionName = variant["$ref"].replace(/^#\/\$defs\//u, "");
    const variantDefinition = definitions[definitionName];
    if (
      definitionName === variant["$ref"] ||
      !isRecord(variantDefinition) ||
      variantDefinition["type"] !== "object" ||
      variantDefinition["additionalProperties"] !== false ||
      !isRecord(variantDefinition["properties"]) ||
      !isStringArray(variantDefinition["required"])
    ) {
      throw new Error("Dashboard event variants must share the closed event envelope");
    }
    const properties = variantDefinition["properties"];
    const required = variantDefinition["required"];
    if (
      JSON.stringify(Object.keys(properties).sort()) !==
        JSON.stringify([...envelopePropertyNames].sort()) ||
      JSON.stringify([...required].sort()) !== JSON.stringify([...envelopePropertyNames].sort())
    ) {
      throw new Error("Dashboard event variants must contain the exact event envelope");
    }
    if (missionSchema === undefined) {
      missionSchema = properties["mission"];
      timeSchema = properties["time"];
    } else if (
      JSON.stringify(properties["mission"]) !== JSON.stringify(missionSchema) ||
      JSON.stringify(properties["time"]) !== JSON.stringify(timeSchema)
    ) {
      throw new Error("Dashboard event variants must share mission and time validation");
    }
    return {
      properties: {
        data: properties["data"],
        eventClass: properties["eventClass"],
        kind: properties["kind"],
      },
    };
  });
  const common = { ...schema };
  Reflect.deleteProperty(common, "anyOf");
  Reflect.deleteProperty(common, "$defs");
  return {
    ...common,
    additionalProperties: false,
    discriminator: { propertyName: "kind" },
    oneOf: factoredVariants,
    properties: {
      data: {},
      eventClass: {},
      kind: {},
      mission: missionSchema,
      time: timeSchema,
    },
    required: envelopePropertyNames,
    type: "object",
  };
}

function resolveReservedSchemaPath(url: string): string {
  const parsed = new URL(url);
  if (
    parsed.origin !== RESERVED_SCHEMA_ORIGIN ||
    parsed.username !== "" ||
    parsed.password !== "" ||
    parsed.search !== "" ||
    !parsed.pathname.startsWith(RESERVED_SCHEMA_PREFIX)
  ) {
    throw new Error(`Refusing non-repository schema reference: ${url}`);
  }

  const relativePath = decodeURIComponent(parsed.pathname.slice(RESERVED_SCHEMA_PREFIX.length));
  const candidate = resolve(schemaRoot, relativePath);
  const candidateRelativePath = relative(schemaRoot, candidate);
  if (
    candidateRelativePath === "" ||
    candidateRelativePath.startsWith("..") ||
    isAbsolute(candidateRelativePath) ||
    !candidate.endsWith(".schema.json")
  ) {
    throw new Error(`Refusing schema reference outside the v1 schema root: ${url}`);
  }
  return candidate;
}

async function readReservedSchema(url: string): Promise<GeneratorSchema> {
  const schemaPath = resolveReservedSchemaPath(url);
  const raw = await readFile(schemaPath, "utf8");
  return parseSchema(raw, schemaPath);
}

function generatedIndex(): string {
  const imports = dashboardSchemas
    .map(({ fileName, typeName }) => `import type { ${typeName} } from "./${fileName}";`)
    .join("\n");
  const exports = dashboardSchemas
    .map(({ fileName, typeName }) => `export type { ${typeName} } from "./${fileName}";`)
    .join("\n");
  const schemaMapping = dashboardSchemas
    .map(({ schemaId, typeName }) => `  readonly "${schemaId}": ${typeName};`)
    .join("\n");

  return `${GENERATED_BANNER}\n\n${imports}\n\n${exports}\n\nexport interface DashboardDocumentBySchemaId {\n${schemaMapping}\n}\n`;
}

function generatedUcs2LengthRuntime(): string {
  return `${GENERATED_BANNER}\n\nexport default function ucs2Length(value) {\n  return Array.from(value).length;\n}\n`;
}

function validatorExportName(fileName: string): string {
  return `validate${fileName
    .split("-")
    .map((part) => `${part[0]?.toUpperCase() ?? ""}${part.slice(1)}`)
    .join("")}`;
}

function browserCompatibleStandalone(source: string): string {
  if (!source.startsWith(REDUNDANT_MODULE_STRICT_PREFIX)) {
    throw new Error("Ajv standalone output did not contain its expected strict-mode prefix");
  }
  const moduleSource = source.slice(REDUNDANT_MODULE_STRICT_PREFIX.length);
  const runtimeLinks = [...moduleSource.matchAll(AJV_UCS2_RUNTIME_REQUIRE)];
  const runtimeBinding = runtimeLinks[0]?.[1];
  if (runtimeLinks.length !== 1 || runtimeBinding === undefined) {
    throw new Error("Ajv standalone output did not contain its one expected UCS-2 runtime link");
  }
  let esmSource = moduleSource.replace(
    runtimeLinks[0]?.[0] ?? "",
    `const ${runtimeBinding} = ajvUcs2LengthRuntime.default;`,
  );
  const equalLinks = [...esmSource.matchAll(AJV_EQUAL_RUNTIME_REQUIRE)];
  if (equalLinks.length > 1) {
    throw new Error("Ajv standalone output contained multiple equality runtime links");
  }
  const equalBinding = equalLinks[0]?.[1];
  if (equalBinding !== undefined) {
    esmSource = esmSource.replace(
      equalLinks[0]?.[0] ?? "",
      `const ${equalBinding} = typeof ajvEqualRuntime === "function" ? ajvEqualRuntime : ajvEqualRuntime.default;`,
    );
  }
  if (COMMONJS_RUNTIME_LINK.test(esmSource)) {
    throw new Error("Ajv standalone output retained an unsupported CommonJS runtime link");
  }
  const equalImport =
    equalBinding === undefined
      ? ""
      : `import ajvEqualRuntime from "${AJV_EQUAL_RUNTIME_MODULE}";\n`;
  return `${equalImport}import * as ajvUcs2LengthRuntime from "${AJV_UCS2_RUNTIME_MODULE}";\n${esmSource}`;
}

async function generateStandaloneValidators(): Promise<string> {
  const ajv = new Ajv2020({
    allErrors: true,
    code: { esm: true, optimize: 2, source: true },
    coerceTypes: false,
    discriminator: true,
    inlineRefs: false,
    loopEnum: 2,
    loopRequired: 3,
    messages: false,
    removeAdditional: false,
    strict: true,
    useDefaults: false,
  });
  const canonicalPath = resolve(schemaRoot, "canonical.schema.json");
  ajv.addSchema(
    withoutRuntimeAnnotations(
      parseSchema(await readFile(canonicalPath, "utf8"), canonicalPath),
    ) as GeneratorSchema,
    `${RESERVED_SCHEMA_ORIGIN}${RESERVED_SCHEMA_PREFIX}canonical.schema.json`,
  );
  const exportsByName: Record<string, string> = {};
  for (const definition of dashboardSchemas) {
    const schemaPath = resolve(dashboardSchemaRoot, `${definition.fileName}.schema.json`);
    const schema = parseSchema(await readFile(schemaPath, "utf8"), schemaPath);
    ajv.addSchema(
      factorRuntimeClosedObjectUnions(
        runtimeOptimizedSchema(definition, withoutRuntimeAnnotations(schema) as GeneratorSchema),
      ) as GeneratorSchema,
      definition.schemaId,
    );
    if (browserBoundarySchemaFiles.has(definition.fileName)) {
      exportsByName[validatorExportName(definition.fileName)] = definition.schemaId;
    }
  }
  const standalone = browserCompatibleStandalone(standaloneCode(ajv, exportsByName));
  const source = `${GENERATED_BANNER}\n\n${standalone}\n`;
  return format(source, {
    parser: "babel",
    printWidth: 100,
    semi: true,
    singleQuote: false,
    trailingComma: "all",
  });
}

async function generateStandaloneDeclarations(): Promise<string> {
  const declarations = dashboardSchemas
    .filter(({ fileName }) => browserBoundarySchemaFiles.has(fileName))
    .map(
      ({ fileName }) =>
        `export declare const ${validatorExportName(fileName)}: DashboardStandaloneValidator;`,
    )
    .join("\n");
  return format(
    `${GENERATED_BANNER}\n\nexport type DashboardStandaloneValidator = (candidate: unknown) => boolean;\n\n${declarations}\n`,
    {
      parser: "typescript",
      printWidth: 100,
      semi: true,
      singleQuote: false,
      trailingComma: "all",
    },
  );
}

async function generateSchema(definition: DashboardSchemaDefinition): Promise<string> {
  const schemaPath = resolve(dashboardSchemaRoot, `${definition.fileName}.schema.json`);
  const parsedSchema = parseSchema(await readFile(schemaPath, "utf8"), schemaPath);
  const schema =
    definition.fileName === "reset-request"
      ? { ...parsedSchema, tsType: "Record<PropertyKey, never>" }
      : parsedSchema;
  const generated = await compileSchema(schema, definition.typeName, {
    $refOptions: {
      resolve: {
        file: false,
        http: false,
        repository: {
          order: 1,
          canRead: (file) => file.url.startsWith(`${RESERVED_SCHEMA_ORIGIN}/`),
          read: async (file) => readReservedSchema(file.url),
        },
      },
    },
    additionalProperties: false,
    bannerComment: GENERATED_BANNER,
    cwd: dashboardSchemaRoot,
    customName: (linkedSchema) => {
      const schemaId = linkedSchema["$id"];
      return typeof schemaId === "string" ? knownTypeNames.get(schemaId) : undefined;
    },
    declareExternallyReferenced: true,
    enableConstEnums: false,
    format: true,
    ignoreMinAndMaxItems: true,
    strictIndexSignatures: true,
    style: {
      bracketSpacing: true,
      printWidth: 100,
      semi: true,
      singleQuote: false,
      trailingComma: "all",
    },
    unknownAny: true,
  });
  return generated.endsWith("\n") ? generated : `${generated}\n`;
}

async function assertSourceInventory(): Promise<void> {
  const expected = dashboardSchemas.map(({ fileName }) => `${fileName}.schema.json`).sort();
  const actual = (await readdir(dashboardSchemaRoot))
    .filter((entry) => entry.endsWith(".schema.json"))
    .sort();
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    throw new Error(
      `Dashboard schema inventory differs: expected ${expected.join(", ")}; found ${actual.join(", ")}`,
    );
  }
}

async function expectedOutputs(): Promise<ReadonlyMap<string, string>> {
  await assertSourceInventory();
  const generatedSchemas = await Promise.all(
    dashboardSchemas.map(
      async (definition) =>
        [`${definition.fileName}.ts`, await generateSchema(definition)] as const,
    ),
  );
  return new Map([
    ...generatedSchemas,
    ["index.ts", generatedIndex()],
    [`${generatedRuntimeDirectory}/ucs2length-runtime.mjs`, generatedUcs2LengthRuntime()],
    [`${generatedRuntimeDirectory}/validators.d.mts`, await generateStandaloneDeclarations()],
    [`${generatedRuntimeDirectory}/validators.mjs`, await generateStandaloneValidators()],
  ]);
}

async function currentGeneratedEntries(
  root = generatedRoot,
  prefix = "",
): Promise<readonly string[]> {
  const entries = await readdir(root, { withFileTypes: true }).catch((error: unknown) => {
    if (isRecord(error) && error["code"] === "ENOENT") {
      return [];
    }
    throw error;
  });
  const descendants = await Promise.all(
    entries.map(async (entry) => {
      const relativeName = prefix === "" ? entry.name : `${prefix}/${entry.name}`;
      return entry.isDirectory()
        ? currentGeneratedEntries(resolve(root, entry.name), relativeName)
        : [relativeName];
    }),
  );
  return descendants.flat().sort();
}

async function refuseUnexpectedGeneratedEntries(expectedNames: readonly string[]): Promise<void> {
  const expected = new Set(expectedNames);
  const extras = (await currentGeneratedEntries()).filter((entry) => !expected.has(entry));
  if (extras.length > 0) {
    throw new Error(`Unexpected generated contract entries: ${extras.join(", ")}`);
  }
}

async function writeOutputs(outputs: ReadonlyMap<string, string>): Promise<void> {
  await refuseUnexpectedGeneratedEntries([...outputs.keys()]);
  await mkdir(generatedRoot, { recursive: true });
  await Promise.all(
    [...outputs].map(async ([fileName, contents]) => {
      const outputPath = resolve(generatedRoot, fileName);
      await mkdir(dirname(outputPath), { recursive: true });
      await writeFile(outputPath, contents, "utf8");
    }),
  );
}

async function checkOutputs(outputs: ReadonlyMap<string, string>): Promise<void> {
  const expectedNames = [...outputs.keys()].sort();
  const actualNames = await currentGeneratedEntries();
  const missing = expectedNames.filter((entry) => !actualNames.includes(entry));
  const extra = actualNames.filter((entry) => !outputs.has(entry));
  const different: string[] = [];

  for (const [fileName, expected] of outputs) {
    if (missing.includes(fileName)) {
      continue;
    }
    const actual = await readFile(resolve(generatedRoot, fileName), "utf8");
    if (actual !== expected) {
      different.push(fileName);
    }
  }

  if (missing.length > 0 || extra.length > 0 || different.length > 0) {
    throw new Error(
      [
        `Generated dashboard contracts are stale.`,
        `Missing: ${missing.join(", ") || "none"}.`,
        `Different: ${different.join(", ") || "none"}.`,
        `Extra: ${extra.join(", ") || "none"}.`,
      ].join(" "),
    );
  }
}

async function main(): Promise<void> {
  const [mode, ...unexpectedArguments] = process.argv.slice(2);
  if ((mode !== "--write" && mode !== "--check") || unexpectedArguments.length > 0) {
    throw new Error("Usage: generate-dashboard-contracts.ts --write|--check");
  }

  const outputs = await expectedOutputs();
  if (mode === "--write") {
    await writeOutputs(outputs);
  } else {
    await checkOutputs(outputs);
  }
}

await main().catch((error: unknown) => {
  const message = error instanceof Error ? error.message : "Unknown contract-generation failure";
  console.error(message);
  process.exitCode = 1;
});
